export interface CollaboratorPermissions {
    can_create: boolean;
    can_edit: 'own' | 'all' | 'none';
    can_delete: 'own' | 'all' | 'none';
    // If empty, ALL types are visible. If populated, ONLY these are visible.
    visible_types: RecordType[]; 
