// Need to duplicate this to avoid circular dependencies if getApiKey is in geminiService which imports supabaseService
// Best practice: Extract this helper to a 'config.ts' or 'authService.ts', but for now duplicating logic.
async function getGeminiApiKeyInternal(settings: SupabaseSettings, accessToken?: string): Promise<string> {
    // 1. Try Production Env Var (Vercel)
    try {
        // @ts-ignore
        const envKey = import.meta.env.VITE_GEMINI_API_KEY;
        if (envKey && envKey.length > 10) return envKey;
    } catch (e) {
        // Ignore error if env not available
    }

    // 2. Fallback: Fetch from Supabase DB (Development / Local)
    const client = createClient(settings.supabaseUrl, settings.supabaseKey, {
        global: { headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined }
    });

    const { data } = await client
        .from('app_secrets')
        .select('value')
        .eq('key_name', 'GEMINI_API_KEY')
        .single();

    if (!data?.value) {
        throw new Error("Missing Gemini Key");
    }
    return data.value;
}


// Proxy strategy same as notionService
const PROXIES = [
  "https://corsproxy.io/?",
  "https://thingproxy.freeboard.io/fetch/"
];

// Robust UUID Generator (Polyfill)
const generateUUID = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
        try {
            return crypto.randomUUID();
        } catch (e) {}
    }
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0;
        const v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
};

async function fetchWithFallback(targetUrl: string, options: RequestInit): Promise<Response> {
  let lastError: any;
  const TIMEOUT_MS = 15000;

  for (const proxyBase of PROXIES) {
    try {
      const url = proxyBase + encodeURIComponent(targetUrl);
      const controller = new AbortController();
      const id = setTimeout(() => controller.abort(), TIMEOUT_MS);

      const response = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(id);

      if (response.status === 401 || response.status === 404) return response;
      if (response.ok) return response;
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError || new Error("Error de conexión con Notion (Proxies fallaron o Timeout)");
}

async function urlToBase64(url: string): Promise<string> {
    try {
        const response = await fetch(url); 
        const blob = await response.blob();
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result as string);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });
    } catch (e) {
        try {
            const response = await fetchWithFallback(url, { method: 'GET' });
            const blob = await response.blob();
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result as string);
                reader.onerror = reject;
                reader.readAsDataURL(blob);
            });
        } catch (err) {
            console.error("Error downloading image", err);
            return "";
        }
    }
}

// Helper to compress Blob
const compressBlob = (blob: Blob): Promise<Blob> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(blob);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const MAX_WIDTH = 800;
                const scaleSize = MAX_WIDTH / img.width;
                const finalWidth = scaleSize < 1 ? MAX_WIDTH : img.width;
                const finalHeight = scaleSize < 1 ? img.height * scaleSize : img.height;

                canvas.width = finalWidth;
                canvas.height = finalHeight;

                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    resolve(blob);
                    return;
                }
                ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

                canvas.toBlob((newBlob) => {
                    if (newBlob) resolve(newBlob);
                    else resolve(blob);
                }, 'image/jpeg', 0.7); // 70% Quality
            };
            img.onerror = (err) => reject(err);
        };
        reader.onerror = (err) => reject(err);
    });
};

// --- NEW MASS DELETE FUNCTION ---
export const deleteMigratedEvents = async (
    supabaseSettings: SupabaseSettings,
    filters: { startDate?: string, endDate?: string },
    onLog: (msg: string) => void,
    accessToken?: string
): Promise<void> => {
    const log = (msg: string) => onLog(`[${new Date().toLocaleTimeString()}] ${msg}`);

    // Create authenticated client
    const client = createClient(supabaseSettings.supabaseUrl, supabaseSettings.supabaseKey, {
        auth: {
            persistSession: false,
            autoRefreshToken: false,
            detectSessionInUrl: false
        },
        global: { headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined }
    });

    log("🔍 Buscando eventos para borrar...");

    // Build Query
    let query = client.from('events').select('id, photo_url');
    if (filters.startDate) query = query.gte('date', filters.startDate);
    if (filters.endDate) query = query.lte('date', filters.endDate);

    const { data: events, error } = await query;

    if (error) throw new Error(`Error buscando eventos: ${error.message}`);
    if (!events || events.length === 0) {
        log("⚠️ No se encontraron eventos en ese rango.");
        return;
    }

    log(`🗑️ Encontrados ${events.length} registros. Procesando borrado...`);

    // 1. Collect all photo files to delete
    const filesToDelete: string[] = [];
    events.forEach((ev: any) => {
        if (ev.photo_url) {
            const parts = ev.photo_url.split('/');
            const fileName = parts[parts.length - 1];
            if (fileName) filesToDelete.push(fileName);
        }
    });

    // 2. Delete from Storage (in batches of 50 just in case)
    if (filesToDelete.length > 0) {
        log(`📸 Borrando ${filesToDelete.length} fotos del almacenamiento...`);
        // Supabase storage remove accepts array of strings
        const { error: storageError } = await client.storage
            .from('dog_photos')
            .remove(filesToDelete);

        if (storageError) log(`⚠️ Error borrando fotos: ${storageError.message}`);
        else log("✅ Fotos eliminadas.");
    }

    // 3. Delete Rows
    log("🗄️ Borrando filas de la base de datos...");
    const idsToDelete = events.map((ev: any) => ev.id);
    const { error: deleteError } = await client
        .from('events')
        .delete()
        .in('id', idsToDelete);

    if (deleteError) throw new Error(`Error borrando filas: ${deleteError.message}`);

    log("✅ Base de datos limpiada con éxito.");
};


// --- ORPHAN RESCUE FUNCTION ---
export const assignOrphanEvents = async (
    settings: SupabaseSettings,
    targetUserId: string,
    targetPetId: string,
    onLog: (msg: string) => void,
    accessToken?: string
): Promise<void> => {
    const log = (msg: string) => onLog(`[${new Date().toLocaleTimeString()}] ${msg}`);
    // Create authenticated client
    const client = createClient(settings.supabaseUrl, settings.supabaseKey, {
        auth: {
            persistSession: false,
            autoRefreshToken: false,
            detectSessionInUrl: false
        },
        global: { headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined }
    });

    log(`🔍 Buscando eventos huérfanos (sin usuario o mascota)...`);

    // Find orphans (rows where user_id IS NULL OR pet_id IS NULL)
    // Note: Supabase JS syntax for OR filters is specific
    const { data: orphans, error: searchError } = await client
        .from('events')
        .select('id')
        .or('user_id.is.null,pet_id.is.null');

    if (searchError) throw new Error(`Error buscando huérfanos: ${searchError.message}`);

    if (!orphans || orphans.length === 0) {
        log("✅ No hay eventos huérfanos. Todo está asignado.");
        return;
    }

    log(`⚠️ Encontrados ${orphans.length} eventos sin asignar.`);
    log(`🔄 Asignando a Usuario: ...${targetUserId.slice(-5)} y Mascota ID: ...${targetPetId.slice(-5)}...`);

    // Update matching rows
    const { error: updateError } = await client
        .from('events')
        .update({ 
            user_id: targetUserId, 
            pet_id: targetPetId 
        })
        .or('user_id.is.null,pet_id.is.null');

    if (updateError) throw new Error(`Error actualizando: ${updateError.message}`);

    log(`🎉 ¡Éxito! Se han rescatado y asignado ${orphans.length} eventos.`);
};

// --- OPTIMIZATION FUNCTION (COMPRESS EXISTING) ---
export const optimizeExistingPhotos = async (
    settings: SupabaseSettings,
    onProgress: (current: number, total: number, msg: string) => void,
    onLog: (msg: string) => void,
    accessToken?: string
): Promise<void> => {
    const log = (msg: string) => onLog(`[${new Date().toLocaleTimeString()}] ${msg}`);

    // Authenticate Client to pass RLS (Use explicit config to avoid local storage conflicts)
    const client = createClient(settings.supabaseUrl, settings.supabaseKey, {
        auth: {
            persistSession: false,
            autoRefreshToken: false,
            detectSessionInUrl: false
        },
        global: {
            headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined
        }
    });

    log("🔍 Buscando eventos con fotos...");

    const { data: events, error } = await client
        .from('events')
        .select('id, title, photo_url')
        .not('photo_url', 'is', null);

    if (error) throw new Error(error.message);

    if (!events || events.length === 0) {
        log("✅ No hay fotos para optimizar.");
        return;
    }

    const total = events.length;
    log(`📸 Encontradas ${total} fotos. Iniciando análisis...`);

    let compressedCount = 0;
    let skippedCount = 0;
    let errorCount = 0;

    for (let i = 0; i < total; i++) {
        const ev = events[i];
        const url = ev.photo_url!;

        onProgress(i + 1, total, `Procesando: ${ev.title}`);

        try {
            // 1. Download
            const response = await fetch(url);
            if (!response.ok) {
                log(`⚠️ Error descargando foto de: ${ev.title} (Status ${response.status})`);
                errorCount++;
                continue;
            }
            const blob = await response.blob();
            const sizeKB = blob.size / 1024;

            // 2. Check Size (Skip if < 150KB)
            if (sizeKB < 150) {
                // log(`⏩ ${ev.title}: Pequeña (${Math.round(sizeKB)}KB). Saltando.`);
                skippedCount++;
                continue;
            }

            // 3. Compress
            log(`📉 Comprimiendo ${ev.title} (${Math.round(sizeKB)}KB)...`);
            const compressedBlob = await compressBlob(blob);
            const newSizeKB = compressedBlob.size / 1024;

            // 4. Upload (Overwrite)
            // Extract filename from URL
            // URL format: .../storage/v1/object/public/dog_photos/uuid/filename.jpg
            const urlObj = new URL(url);
            const pathParts = urlObj.pathname.split('/dog_photos/'); // Split by bucket name
            if (pathParts.length < 2) {
                log(`⚠️ No pude extraer ruta de: ${url}`);
                errorCount++;
                continue;
            }
            const storagePath = decodeURIComponent(pathParts[1]); // e.g. "pet_id/timestamp.jpg"

            // Attempt 1: Standard Upsert
            const { error: uploadError } = await client.storage
                .from('dog_photos')
                .upload(storagePath, compressedBlob, {
                    contentType: 'image/jpeg',
                    upsert: true 
                });

            if (uploadError) {
                // Handle RLS Violation: Policy might allow Insert/Delete but not Update.
                // Fallback: Delete original -> Upload new
                const isRlsError = (uploadError as any).code === '42501' || uploadError.message.includes('row-level security');

                if (isRlsError) {
                    log(`⚠️ Upsert bloqueado por RLS. Intentando reemplazo (Borrar -> Subir)...`);

                    const { error: removeError } = await client.storage.from('dog_photos').remove([storagePath]);
                    if (removeError) {
                        log(`❌ Falló borrado previo: ${removeError.message}`);
                        errorCount++;
                        continue;
                    }

                    const { error: retryError } = await client.storage
                        .from('dog_photos')
                        .upload(storagePath, compressedBlob, {
                            contentType: 'image/jpeg',
                            upsert: false // Now it's a fresh insert
                        });

                    if (retryError) {
                        log(`❌ Falló la re-subida: ${retryError.message}`);
                        errorCount++;
                        continue;
                    } else {
                        const saving = Math.round(((sizeKB - newSizeKB) / sizeKB) * 100);
                        log(`✅ Optimizado (vía Reemplazo): ${Math.round(newSizeKB)}KB (Ahorro: ${saving}%)`);
                        compressedCount++;
                    }
                } else {
                    log(`❌ Error subiendo: ${uploadError.message}`);
                    errorCount++;
                }
            } else {
                const saving = Math.round(((sizeKB - newSizeKB) / sizeKB) * 100);
                log(`✅ Optimizado: ${Math.round(newSizeKB)}KB (Ahorro: ${saving}%)`);
                compressedCount++;
            }

        } catch (e: any) {
            log(`❌ Excepción en ${ev.title}: ${e.message}`);
            errorCount++;
        }
    }

    log(`🏁 FINALIZADO. Comprimidas: ${compressedCount}, Saltadas: ${skippedCount}, Errores: ${errorCount}`);
};

// --- NEW FUNCTION: BATCH SCORE POOPS ---
export const batchScorePoops = async (
    settings: SupabaseSettings,
    onProgress: (current: number, total: number, msg: string) => void,
    onLog: (msg: string) => void,
    accessToken?: string
): Promise<void> => {
    const log = (msg: string) => onLog(`[${new Date().toLocaleTimeString()}] ${msg}`);

    try {
        const apiKey = await getGeminiApiKeyInternal(settings, accessToken);
        const ai = new GoogleGenAI({ apiKey });

        // Create client
        const client = createClient(settings.supabaseUrl, settings.supabaseKey, {
            global: { headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined }
        });

        log("🔍 Buscando registros de 'Caca' sin puntuación...");

        // Note: 'is' null check syntax
        const { data: events, error } = await client
            .from('events')
            .select('id, title, description, photo_url')
            .eq('record_type', 'Caca')
            .is('poop_score', null);

        if (error) throw new Error(error.message);

        if (!events || events.length === 0) {
            log("✅ No hay registros pendientes de puntuar.");
            return;
        }

        const total = events.length;
        log(`📋 Encontrados ${total} registros. Iniciando IA...`);

        let updatedCount = 0;

        for (let i = 0; i < total; i++) {
            const ev = events[i];
            onProgress(i + 1, total, `Puntuando: ${ev.title}`);

            try {
                // Determine content for AI
                const prompt = `Analiza este registro de heces de perro y asigna una puntuación del 1 al 10 (1=Diarrea grave, 10=Perfecta). 
                Solo devuelve el número JSON: {"score": number}.
                Título: ${ev.title}. Descripción: ${ev.description || "N/A"}.`;

                const parts: any[] = [{ text: prompt }];

                if (ev.photo_url) {
                    try {
                        const imgBase64 = await urlToBase64(ev.photo_url);
                        if (imgBase64) {
                            parts.push({
                                inlineData: {
                                    mimeType: 'image/jpeg',
                                    data: imgBase64.split(',')[1]
                                }
                            });
                        }
                    } catch (imgErr) {
                        log(`⚠️ No pude descargar imagen de ${ev.title}, usando solo texto.`);
                    }
                }

                // Call Gemini
                const response = await ai.models.generateContent({
                    model: 'gemini-2.0-flash',
                    contents: { parts },
                    config: {
                        responseMimeType: 'application/json',
                        responseSchema: {
                            type: Type.OBJECT,
                            properties: {
                                score: { type: Type.INTEGER }
                            }
                        }
                    }
                });

                const result = JSON.parse(response.text || "{}");

                if (result.score) {
                    // Update DB
                    const { error: updateError } = await client
                        .from('events')
                        .update({ poop_score: result.score })
                        .eq('id', ev.id);

                    if (updateError) {
                        log(`❌ Error guardando score para ${ev.title}: ${updateError.message}`);
                    } else {
                        updatedCount++;
                        // log(`✅ ${ev.title} -> Score: ${result.score}`);
                    }
                }

                // Rate limit guard (simple)
                await new Promise(r => setTimeout(r, 500)); 

            } catch (e: any) {
                log(`❌ Error procesando ${ev.title}: ${e.message}`);
            }
        }

        log(`🏁 FINALIZADO. Puntuados: ${updatedCount}/${total}`);

    } catch (e: any) {
        log(`❌ Error General: ${e.message}`);
    }
};


// --- MIGRATION FUNCTION ---
export const startMigration = async (
    notionSettings: { apiKey: string, databaseId: string },
    supabaseSettings: SupabaseSettings,
    filters: { startDate?: string, endDate?: string },
    onProgress: (current: number, total: number, status: string) => void,
    onLog: (msg: string) => void,
    accessToken?: string
): Promise<{ success: boolean }> => {

    const log = (msg: string) => {
        const timeMsg = `[${new Date().toLocaleTimeString()}] ${msg}`;
        console.log(timeMsg);
        onLog(timeMsg);
    };

    const apiKey = notionSettings.apiKey.trim();
    const dbId = notionSettings.databaseId.trim();

    try {
        log("⚙️ Preparando consulta a Notion...");

        let allResults: any[] = [];
        let hasMore = true;
        let cursor: string | undefined = undefined;

        // Construct Notion Filter Object
        const notionFilters: any[] = [];
        if (filters.startDate) {
            notionFilters.push({ property: "Fecha", date: { on_or_after: filters.startDate } });
        }
        if (filters.endDate) {
            notionFilters.push({ property: "Fecha", date: { on_or_before: filters.endDate } });
        }

        const filterPayload = notionFilters.length > 0 
            ? (notionFilters.length === 1 ? notionFilters[0] : { and: notionFilters }) 
            : undefined;

        if (filterPayload) {
            log(`🔎 Aplicando filtro Notion: ${JSON.stringify(filterPayload)}`);
        }

        // 1. Fetch Loop
        while (hasMore) {
            const url = `https://api.notion.com/v1/databases/${dbId}/query`;
            const body: any = { 
                page_size: 50,
                filter: filterPayload
            };
            if (cursor) body.start_cursor = cursor;

            const response = await fetchWithFallback(url, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${apiKey}`,
                    'Notion-Version': '2022-06-28',
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(body)
            });

            if (!response.ok) {
                const errText = await response.text();
                throw new Error(`Error Notion (${response.status}): ${errText}`);
            }

            const data = await response.json();
            allResults = [...allResults, ...data.results];
            hasMore = data.has_more;
            cursor = data.next_cursor;

            onProgress(allResults.length, -1, `Descargando: ${allResults.length} encontrados...`);
        }

        const total = allResults.length;
        log(`📋 TOTAL A PROCESAR: ${total} registros.`);

        if (total === 0) {
            log("⚠️ No se encontraron registros con esos filtros.");
            return { success: true };
        }

        // 2. Process
        for (let i = 0; i < total; i++) {
            const page = allResults[i];
            const props = page.properties;

            // Title
            const titleList = props['Título']?.title || [];
            let title = titleList.length > 0 ? titleList[0].plain_text : "Sin título";

            onProgress(i + 1, total, `Migrando ${i + 1}/${total}: ${title}`);

            // Type
            let recordTypeStr = props['Tipo de registro']?.select?.name || "Resumen";
            let recordType = Object.values(RecordType).find(r => r === recordTypeStr) || RecordType.SUMMARY;

            // --- STRICT DATE/TIME PARSING (Fixing Timezone Issues) ---

            // 1. Date: Notion returns "YYYY-MM-DD" in date.start
            let dateStr = props['Fecha']?.date?.start || "";

            // 2. Time: Search in 'Hora' Text Column
            let timeStr = "";
            const horaRichText = props['Hora']?.rich_text;
            if (horaRichText && horaRichText.length > 0) {
                // Assuming format "HH:mm" in text
                timeStr = horaRichText[0].plain_text.trim();
            }

            // Fallbacks
            if (!dateStr) dateStr = new Date().toISOString().split('T')[0]; // Only if missing
            if (!timeStr) timeStr = "12:00"; // Default noon if missing

            // Description
            const descList = props['Descripción']?.rich_text || [];
            let description = descList.map((t: any) => t.plain_text).join("");

            // Health
            const statusStr = props['Estado de Salud']?.select?.name;
            let healthStatus = Object.values(HealthStatus).find(s => s === statusStr) || null;

            // Weight
            const weight = props['Peso']?.number || undefined;

            // Photo
            let photoBase64: string | undefined = undefined;
            const files = props['Foto']?.files || props['Archivos']?.files || [];

            if (files.length > 0) {
                const fileUrl = files[0].file?.url || files[0].external?.url;
                if (fileUrl) {
                    log(`   📸 Descargando foto...`);
                    photoBase64 = await urlToBase64(fileUrl);
                }
            }

            // --- NO AI ---

            const newEvent: DogEvent = {
                id: generateUUID(), 
                title,
                recordType: recordType as RecordType,
                date: dateStr,
                time: timeStr,
                description,
                healthStatus: healthStatus as HealthStatus,
                weight,
                photoBase64,
                synced: false
            };

            // Pass accessToken to ensure ownership is correctly assigned (if implicit in backend trigger) 
            // and RLS allows insert.
            const saveResult = await saveEventToSupabase(newEvent, supabaseSettings, accessToken);

            if (!saveResult.success) {
                log(`   ❌ Error guardando: ${saveResult.error}`);
            }
        }

        log("✅ Migración completada exitosamente.");
        return { success: true };

    } catch (error: any) {
        log(`❌ Error CRÍTICO Migración: ${error.message}`);
        return { success: false };
    }
};

import React, { useState, useRef, useEffect } from 'react';
import { SupabaseSettings, Pet } from '../types';
import { startMigration, deleteMigratedEvents, assignOrphanEvents, optimizeExistingPhotos, batchScorePoops } from '../services/migrationService';

interface MigrationPanelProps {
    supabaseSettings: SupabaseSettings;
    currentPet?: Pet | null;
    currentUser?: any;
    accessToken?: string;
}

const MigrationPanel: React.FC<MigrationPanelProps> = ({ supabaseSettings, currentPet, currentUser, accessToken }) => {
    const [isOpen, setIsOpen] = useState(false);

    // Inputs
    const [notionKey, setNotionKey] = useState('');
    const [dbId, setDbId] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    const [status, setStatus] = useState<'idle' | 'confirming_migration' | 'confirming_deletion' | 'confirming_rescue' | 'confirming_optimization' | 'confirming_scoring' | 'running' | 'done'>('idle');
    const [progress, setProgress] = useState({ current: 0, total: 0, msg: '' });
    const [logs, setLogs] = useState<string[]>([]);
    const logsEndRef = useRef<HTMLDivElement>(null);

    // Auto-scroll logs
    useEffect(() => {
        if (logsEndRef.current) {
            logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [logs]);

    // Helpers to manage UI blocking
    const handleActionClick = (e: React.MouseEvent, action: 'migration' | 'deletion' | 'rescue' | 'optimization' | 'scoring') => {
        e.preventDefault();
        e.stopPropagation();

        if (action === 'migration' && (!notionKey || !dbId)) {
            alert("Faltan datos de Notion.");
            return;
        }
        if (!supabaseSettings.supabaseUrl) {
            alert("Supabase no configurado.");
            return;
        }

        if (action === 'rescue' && (!currentPet || !currentUser)) {
            alert("Necesitas estar logueado y tener una mascota activa.");
            return;
        }

        if (action === 'migration') setStatus('confirming_migration');
        else if (action === 'deletion') setStatus('confirming_deletion');
        else if (action === 'rescue') setStatus('confirming_rescue');
        else if (action === 'scoring') setStatus('confirming_scoring');
        else setStatus('confirming_optimization');
    };

    const runProcess = (type: 'migration' | 'deletion' | 'rescue' | 'optimization' | 'scoring') => {
        setStatus('running');
        let initialLog: string[] = [];

        if (type === 'migration') initialLog = ["🚀 Inicializando migración...", `📅 Filtro: ${startDate || 'Inicio'} a ${endDate || 'Fin'}`];
        else if (type === 'deletion') initialLog = ["🗑️ Inicializando borrado...", `📅 Filtro: ${startDate || 'Inicio'} a ${endDate || 'Fin'}`];
        else if (type === 'rescue') initialLog = ["🛟 Rescatando huérfanos..."];
        else if (type === 'optimization') initialLog = ["⚡ Iniciando optimización de imágenes...", "Esto puede tardar unos minutos."];
        else if (type === 'scoring') initialLog = ["💩 Iniciando IA para puntuar cacas antiguas...", "Esto consumirá tokens de IA."];

        setLogs(initialLog);

        setTimeout(async () => {
            try {
                const filters = {
                    startDate: startDate || undefined,
                    endDate: endDate || undefined
                };

                const logger = (msg: string) => setLogs(prev => [...prev, msg]);

                if (type === 'migration') {
                    await startMigration(
                        { apiKey: notionKey, databaseId: dbId },
                        supabaseSettings,
                        filters,
                        (current, total, msg) => setProgress({ current, total, msg }),
                        logger,
                        accessToken
                    );
                } else if (type === 'deletion') {
                    await deleteMigratedEvents(
                        supabaseSettings,
                        filters,
                        logger,
                        accessToken
                    );
                } else if (type === 'rescue') {
                    if (currentPet && currentUser) {
                        await assignOrphanEvents(
                            supabaseSettings,
                            currentUser.id,
                            currentPet.id,
                            logger,
                            accessToken
                        );
                    } else {
                        throw new Error("Faltan datos de usuario/mascota.");
                    }
                } else if (type === 'optimization') {
                    await optimizeExistingPhotos(
                        supabaseSettings,
                        (current, total, msg) => setProgress({ current, total, msg }),
                        logger,
                        accessToken
                    );
                } else if (type === 'scoring') {
                    await batchScorePoops(
                        supabaseSettings,
                        (current, total, msg) => setProgress({ current, total, msg }),
                        logger,
                        accessToken
                    );
                }

                setLogs(prev => [...prev, "🏁 OPERACIÓN FINALIZADA."]);
                setStatus('done');
            } catch (err: any) {
                setLogs(prev => [...prev, `❌ ERROR FATAL: ${err.message}`]);
                setStatus('done');
            }
        }, 100);
    };

    if (!isOpen) {
        return (
            <div className="mt-8 border-t border-slate-100 pt-6">
                 <button 
                    type="button"
                    onClick={(e) => { e.preventDefault(); setIsOpen(true); }}
                    className="text-xs text-slate-400 hover:text-slate-600 underline"
                >
                    Herramientas de Migración (Beta)
                </button>
            </div>
        );
    }

    return (
        <div className="mt-6 bg-slate-50 border border-slate-200 rounded-xl p-4 animate-fade-in-up">
            <h3 className="font-bold text-slate-700 mb-2">Gestión de Datos: Notion a Supabase</h3>

            <div className="space-y-3">
                {/* Notion Config */}
                <div className="grid grid-cols-1 gap-2">
                    <input 
                        type="password" 
                        value={notionKey} 
                        onChange={e => setNotionKey(e.target.value)}
                        className="w-full p-2 rounded-lg border border-slate-200 text-xs"
                        placeholder="Notion Secret Key (secret_...)"
                        disabled={status === 'running'}
                    />
                    <input 
                        type="text" 
                        value={dbId} 
                        onChange={e => setDbId(e.target.value)}
                        className="w-full p-2 rounded-lg border border-slate-200 text-xs"
                        placeholder="Notion Database ID"
                        disabled={status === 'running'}
                    />
                </div>

                {/* Date Filters */}
                <div className="bg-white p-3 rounded-lg border border-slate-200">
                    <label className="block text-xs font-bold text-slate-500 mb-2 uppercase">Filtros de Acción</label>
                    <div className="grid grid-cols-2 gap-2">
                        <div>
                            <span className="text-[10px] text-slate-400">Desde (Incluido)</span>
                            <input 
                                type="date" 
                                value={startDate} 
                                onChange={e => setStartDate(e.target.value)}
                                className="w-full p-2 rounded-lg border border-slate-200 text-xs"
                                disabled={status === 'running'}
                            />
                        </div>
                        <div>
                            <span className="text-[10px] text-slate-400">Hasta (Incluido)</span>
                            <input 
                                type="date" 
                                value={endDate} 
                                onChange={e => setEndDate(e.target.value)}
                                className="w-full p-2 rounded-lg border border-slate-200 text-xs"
                                disabled={status === 'running'}
                            />
                        </div>
                    </div>
                    <p className="text-[10px] text-slate-400 mt-1 italic">
                        Si dejas las fechas vacías, las acciones afectarán a <strong>TODO</strong> el historial.
                    </p>
                </div>

                {/* Progress Bar */}
                {status === 'running' && (
                    <div className="bg-white p-3 rounded-lg border border-blue-100">
                        <div className="flex justify-between text-xs font-bold text-blue-600 mb-1">
                            <span className="truncate pr-2">{progress.msg || "Procesando..."}</span>
                            <span>{progress.total > 0 ? `${Math.round((progress.current / progress.total) * 100)}%` : ''}</span>
                        </div>
                        <div className="w-full bg-slate-100 rounded-full h-2">
                            <div 
                                className="bg-blue-500 h-2 rounded-full transition-all duration-300" 
                                style={{ width: `${progress.total > 0 ? (progress.current / progress.total) * 100 : 0}%` }}
                            ></div>
                        </div>
                    </div>
                )}

                {/* Action Buttons */}
                {status === 'idle' && (
                    <div className="flex flex-col gap-2 pt-2">
                        <button 
                            type="button"
                            onClick={(e) => handleActionClick(e, 'migration')}
                            className="w-full py-2.5 bg-indigo-600 text-white rounded-lg font-bold text-sm shadow-sm active:scale-95"
                        >
                            Importar de Notion (con Filtro)
                        </button>

                        <div className="flex gap-2">
                            <button 
                                type="button"
                                onClick={(e) => handleActionClick(e, 'optimization')}
                                className="flex-1 py-2.5 bg-amber-500 text-white rounded-lg font-bold text-sm shadow-sm active:scale-95"
                            >
                                ⚡ Optimizar Fotos
                            </button>
                            <button 
                                type="button"
                                onClick={(e) => handleActionClick(e, 'scoring')}
                                className="flex-1 py-2.5 bg-fuchsia-600 text-white rounded-lg font-bold text-sm shadow-sm active:scale-95"
                            >
                                🤖 Puntuar Cacas
                            </button>
                        </div>

                        <button 
                            type="button"
                            onClick={(e) => handleActionClick(e, 'rescue')}
                            className="w-full py-2.5 bg-teal-600 text-white rounded-lg font-bold text-sm shadow-sm active:scale-95"
                        >
                            Asignar Huérfanos a {currentPet?.name || 'Actual'}
                        </button>

                        <button 
                            type="button"
                            onClick={(e) => handleActionClick(e, 'deletion')}
                            className="w-full py-2.5 bg-white border border-red-200 text-red-600 rounded-lg font-bold text-sm shadow-sm active:scale-95 hover:bg-red-50"
                        >
                            Borrar Rango en Supabase
                        </button>
                    </div>
                )}

                {/* Confirmation States */}
                {status === 'confirming_migration' && (
                    <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100">
                        <p className="text-xs font-bold text-indigo-900 mb-2">
                            ¿Importar eventos {startDate ? `desde ${startDate}` : 'desde el inicio'} {endDate ? `hasta ${endDate}` : 'hasta hoy'}?
                        </p>
                        <div className="flex gap-2">
                            <button type="button" onClick={() => setStatus('idle')} className="flex-1 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg text-xs font-bold">Cancelar</button>
                            <button type="button" onClick={() => runProcess('migration')} className="flex-1 py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold shadow-sm">Sí, Importar</button>
                        </div>
                    </div>
                )}

                {status === 'confirming_rescue' && (
                    <div className="bg-teal-50 p-3 rounded-lg border border-teal-100">
                        <p className="text-xs font-bold text-teal-900 mb-2">
                            ¿Asignar todos los eventos sin dueño a {currentPet?.name}?
                        </p>
                        <div className="flex gap-2">
                            <button type="button" onClick={() => setStatus('idle')} className="flex-1 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg text-xs font-bold">Cancelar</button>
                            <button type="button" onClick={() => runProcess('rescue')} className="flex-1 py-2 bg-teal-600 text-white rounded-lg text-xs font-bold shadow-sm">Sí, Asignar</button>
                        </div>
                    </div>
                )}

                {status === 'confirming_optimization' && (
                    <div className="bg-amber-50 p-3 rounded-lg border border-amber-100">
                        <p className="text-xs font-bold text-amber-900 mb-2">
                            Esto descargará, comprimirá y re-subirá todas las fotos grandes. Puede tardar un rato. ¿Seguro?
                        </p>
                        <div className="flex gap-2">
                            <button type="button" onClick={() => setStatus('idle')} className="flex-1 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg text-xs font-bold">Cancelar</button>
                            <button type="button" onClick={() => runProcess('optimization')} className="flex-1 py-2 bg-amber-500 text-white rounded-lg text-xs font-bold shadow-sm">Sí, Optimizar</button>
                        </div>
                    </div>
                )}

                 {status === 'confirming_scoring' && (
                    <div className="bg-fuchsia-50 p-3 rounded-lg border border-fuchsia-100">
                        <p className="text-xs font-bold text-fuchsia-900 mb-2">
                            La IA leerá todas las descripciones de 'Caca' sin puntuar y asignará una nota (1-10).
                        </p>
                        <div className="flex gap-2">
                            <button type="button" onClick={() => setStatus('idle')} className="flex-1 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg text-xs font-bold">Cancelar</button>
                            <button type="button" onClick={() => runProcess('scoring')} className="flex-1 py-2 bg-fuchsia-600 text-white rounded-lg text-xs font-bold shadow-sm">Sí, Puntuar</button>
                        </div>
                    </div>
                )}

                {status === 'confirming_deletion' && (
                    <div className="bg-red-50 p-3 rounded-lg border border-red-100">
                        <p className="text-xs font-bold text-red-900 mb-2">
                            ⚠️ PELIGRO: Se borrarán PERMANENTEMENTE fotos y registros de Supabase {startDate ? `desde ${startDate}` : ''} {endDate ? `hasta ${endDate}` : ''}.
                        </p>
                        <div className="flex gap-2">
                            <button type="button" onClick={() => setStatus('idle')} className="flex-1 py-2 bg-white border border-slate-200 text-slate-600 rounded-lg text-xs font-bold">Cancelar</button>
                            <button type="button" onClick={() => runProcess('deletion')} className="flex-1 py-2 bg-red-600 text-white rounded-lg text-xs font-bold shadow-sm">Sí, Borrar Todo</button>
                        </div>
                    </div>
                )}

                {status === 'done' && (
                    <button 
                        type="button"
                        onClick={() => setStatus('idle')}
                        className="w-full py-2 bg-green-600 text-white rounded-lg font-bold text-sm"
                    >
                        Listo (Volver)
                    </button>
                )}

                {/* LOGS WINDOW */}
                {(status === 'running' || status === 'done' || logs.length > 0) && (
                    <div className="mt-4 p-3 bg-slate-900 text-green-400 text-[10px] font-mono rounded-lg h-40 overflow-y-auto shadow-inner">
                        {logs.map((line, i) => <div key={i} className="border-b border-white/5 py-0.5 break-all">{line}</div>)}
                        <div ref={logsEndRef} />
                    </div>
                )}
            </div>

            <button type="button" onClick={(e) => { e.preventDefault(); setIsOpen(false); }} className="mt-4 text-xs text-slate-400 underline w-full text-center">
                Ocultar panel
            </button>
        </div>
    );
};

