                  <>
                  {[
                    {m:'voice',i:<Icons.Mic className="w-6"/>,t:'Voz',c:'bg-blue-100 text-blue-600'},
                    {m:'chat',i:<Icons.MessageSquare className="w-6"/>,t:'Chat',c:'bg-purple-100 text-purple-600'},
